`resetall
`timescale 1 ps/1 ps

module `IP_MODULE_NAME(efx_command_ctl)
  (
   //Inputs
   input rst_in,
   input clk_in,
   input wren,
   input shift_bytes, 
   input fast_read,             //Fast Read Control 
   input fast_read_dual,        //Fast Read Dual Control 
   input quad_fast_read,        //Quad Fast Read Control 
   input quad_io_fast_read,	//Quad IO Fast Read Control
   input sector_erase,          //Sector Erase Control
   input page_write,            //Page Write Control
   input quad_page_write,	//Quad page write control
   input quad_enable,
   input busy, 
   input [7:0] flash_rd_status_reg0,
   input [7:0] flash_rd_status_reg1,
   input data_valid,
   //Outputs
   output reg [8:0] byte_cnt_out,
   output spi_cmd_en,             
   output [4:0] spi_cmd,
   output [7:0] spi_wr_data,            
   output [7:0] spi_cmd_instr,
   output busy_out                 //This is final busy status, which indicate the instruction busy status. 
   );


//Internal Signals

   reg [4:0] 	current_st, next_st;

   reg 		spi_cmd_en_0;
   reg 		spi_cmd_en_1;
   reg [4:0] 	spi_cmd_0;
   reg [7:0] 	spi_wr_data_0;
   reg [7:0] 	spi_cmd_instr_0;

   reg [7:0] 	spi_wr_data_1;
   reg [7:0] 	spi_cmd_instr_1;
   reg [4:0] 	instr1_1;
   reg [4:0] 	instr2_1;
   reg [4:0] 	instr1_0;
   reg [4:0] 	instr2_0;

   reg 		busy_1;
   reg [4:0] 	spi_cmd_1;
   reg [8:0] 	byte_cnt;
   reg [5:0] 	soft_reset;
   reg [2:0]	wait_cnt, next_wait_cnt;

   reg 		check_busy_0, check_busy_1;
   

//////////////////////////////////   
//RTL
//////////////////////////////////

   assign busy_out = busy_1;
   
   assign spi_cmd = spi_cmd_1;
   assign spi_cmd_en = spi_cmd_en_1;
   
   assign spi_cmd_instr = spi_cmd_instr_1;
   assign spi_wr_data = spi_wr_data_1;
   
   
/////////////////////////
//Page Write Steps
/////////////////////////
//Write Enable
//Page Program
//Page Done? [Check the status register?]

//Test Case   
//$display("IP Command : Write Enable");
//jtag_intreg_write(`INTREG_IP_CMD,8'h83); //Write Enable Instruction Command. 
//jtag_intreg_write(`INTREG_IP_CMD,8'h00); //Clear Write Enable Instruction Command
//
//$display("HOST START SPI WRITE BURST to SPI FLASH.");
//$display("IP Command : Write");
//jtag_intreg_write(`INTREG_IP_CMD,8'h8c); //Write Instruction Command.
//jtag_intreg_write(`INTREG_IP_CMD,8'h00); //Write Instruction Command.

//Main FSM to handle all command/instructions
   localparam ST_IDLE   = 5'h0;
   localparam ST_CMD0_0 = 5'h1;
   localparam ST_CMD0_1 = 5'h2;
   localparam ST_CMD0_2 = 5'h3;
   localparam ST_CMD0_3 = 5'h4;
   localparam ST_CMD1_0 = 5'h5;
   localparam ST_CMD1_1 = 5'h6;
   localparam ST_CMD1_2 = 5'h7;
   localparam ST_CMD1_3 = 5'h8;
   localparam ST_CMD2_0 = 5'h9;
   localparam ST_CMD2_1 = 5'hA;
   localparam ST_CMD2_2 = 5'hB;
   localparam ST_CMD2_3 = 5'hC;
   localparam ST_CHECK_STATUS0 = 5'hD;
   localparam ST_CHECK_STATUS1 = 5'hE;
   localparam ST_CHECK_STATUS2 = 5'hF;
   localparam ST_REG2_STATUS0 = 5'h10;
   localparam ST_REG2_STATUS1 = 5'h11;
   localparam ST_REG2_STATUS2 = 5'h12;
   localparam ST_WREG2_0 = 5'h13;
   localparam ST_WREG2_1 = 5'h14;
   localparam ST_WREG2_2 = 5'h15;
   localparam ST_WREG2_3 = 5'h16;
   localparam ST_WREG2_4 = 5'h17;
 
  
always @(posedge clk_in)
  if (rst_in) begin
    current_st <= ST_IDLE;
    wait_cnt <= 3'd0;
  end
  else begin
    wait_cnt <= next_wait_cnt;
    current_st <= next_st;
  end
   
always @(*)
  begin
     next_wait_cnt = wait_cnt;
     next_st = current_st;
     spi_cmd_en_0 = 1'b0;
     spi_cmd_0 = 5'd0;
     spi_wr_data_0 = spi_wr_data_1;
     spi_cmd_instr_0 = spi_cmd_instr_1;

     instr1_0 = instr1_1;
     instr2_0 = instr2_1;

     check_busy_0 = check_busy_1;
     
     case (current_st)
       ST_IDLE: begin
	  //To decide which instruction to kick off.
	  if (sector_erase) begin 
	     next_st = ST_CMD0_0;
	     instr1_0 = 5'h8;
	     instr2_0 = 5'hd;             //Sector Erase
	     check_busy_0 = 1'b1;
	  end
	  
	  else if (fast_read) begin 
	     next_st = ST_CMD1_0;         //Skip WEL
	     instr1_0 = 5'h8;
	     instr2_0 = 5'h14;            //Fast Read
	     check_busy_0 = 1'b0;
	  end

	  else if (fast_read_dual) begin 
	     next_st = ST_CMD1_0;         //Skip WEL
	     instr1_0 = 5'h8;
	     instr2_0 = 5'h15;            //Fast Read Dual
	     check_busy_0 = 1'b0;
	  end
	  
	  else if (quad_fast_read) begin 
	     next_st = ST_CMD1_0;         //Skip WEL
	     instr1_0 = 5'h8;
	     instr2_0 = 5'h17;            //Fast Read Dual
	     check_busy_0 = 1'b0;
	  end
	  
	  else if (page_write) begin 
	     next_st = ST_CMD0_0;
	     instr1_0 = 5'h8;
	     instr2_0 = 5'hc;             //Page Write
	     check_busy_0 = 1'b1; 
	  end

	  else if (quad_page_write) begin 
	     next_st = ST_CMD0_0;
	     instr1_0 = 5'h8;
	     instr2_0 = 5'h16;             //Quad Page Write
	     check_busy_0 = 1'b1; 
	  end

	  else if (quad_enable) begin 
	     next_st = ST_REG2_STATUS0;
	     instr1_0 = 5'h8;
	     instr2_0 = 5'ha;            //Quad Enable - read statreg2 first then write enable, finally write reg2
	     check_busy_0 = 1'b1; 
	  end


	  else if (soft_reset[5]) begin
	     next_st = ST_CMD1_0;         //Skip WEL
	     instr1_0 = 5'h8;
	     instr2_0 = 5'h1;             //Soft Reset
	     check_busy_0 = 1'b1;
	  end
	  
	   
       end

       ST_CMD0_0: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b1;
	  spi_cmd_0 = instr1_1;         //Write Enable Instruction
	  next_st = ST_CMD0_1;
  
       end

       ST_CMD0_1: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     //Clear the cmd_en
	  spi_cmd_0 = instr1_1;         
	  next_st = ST_CMD0_2;
       end

       ST_CMD0_2: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     
	  spi_cmd_0 = instr1_1;
          if (busy)                //Check for busy status 
	    next_st = ST_CMD0_3;
       end

       ST_CMD0_3 : begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     
	  spi_cmd_0 = instr1_1;
	  if (~busy)
	    next_st = ST_CMD1_0;
       end


       ST_CMD1_0: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b1;
	  spi_cmd_0 = instr2_1;         //Sector Erase Instruction
	  next_st = ST_CMD1_1;
  
       end

       ST_CMD1_1: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     //Clear the cmd_en
	  spi_cmd_0 = instr2_1;         
	  next_st = ST_CMD1_2;
       end

       ST_CMD1_2: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     
	  spi_cmd_0 = instr2_1;
          if (busy)                //Check for busy status 
	    next_st = ST_CMD1_3;
       end

       ST_CMD1_3 : begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     
	  spi_cmd_0 = instr2_1;
	  if (~busy) begin 
	     if (check_busy_1)
	       next_st = ST_CMD2_0;
	     else 
	       next_st = ST_IDLE;
	  end
       end // case: ST_CMD1_3
       
	  
       ST_CMD2_0: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b1;
	  spi_cmd_0 = 5'd14;         //Read Status Register 1
	  next_st = ST_CMD2_1;
       end
       

       ST_CMD2_1: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     //Clear the cmd_en
	  spi_cmd_0 = 5'd14;         
	  next_st = ST_CMD2_2;
       end

       ST_CMD2_2: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     
	  spi_cmd_0 = 5'd14;
          if (busy)                //Check for busy status 
	    next_st = ST_CMD2_3;
       end

       ST_CMD2_3 : begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     
	  spi_cmd_0 = 5'd14;
	  if (~busy)
	    next_st = ST_CHECK_STATUS0;
       end

       ST_CHECK_STATUS0 : next_st = ST_CHECK_STATUS1;
       ST_CHECK_STATUS1 : next_st = ST_CHECK_STATUS2;
       
       ST_CHECK_STATUS2 : begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     
	  spi_cmd_0 = 5'd14;
	  if (~flash_rd_status_reg0[0])
	    next_st = ST_IDLE;
	  else
	    next_st = ST_CMD2_0;
       end

       ST_REG2_STATUS0 : begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b1;     
	  spi_cmd_0 = 5'd15;
	  next_wait_cnt = 3'd0;
	  next_st = ST_REG2_STATUS1;
       end

       ST_REG2_STATUS1 : begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     
	  spi_cmd_0 = 5'd15;
	  if (busy == 1'b0 && wait_cnt >= 3'd3) begin
	     next_wait_cnt = 3'd0;
	     next_st = ST_REG2_STATUS2;
	  end
	  else begin
	     next_wait_cnt = wait_cnt + 1'b1;
          end
       end
       
       ST_REG2_STATUS2 : begin
	  if (flash_rd_status_reg1[1])
	    next_st = ST_IDLE;		// QUAD_ENABLE already on, no action
          else begin  
	    next_st = ST_WREG2_0;	// write status reg2
    	  end
       end

       ST_WREG2_0 : begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b1;
	  spi_cmd_0 = instr1_1;         //Write Enable Instruction
	  next_st = ST_WREG2_1;
       end

       ST_WREG2_1: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     //Clear the cmd_en
	  spi_cmd_0 = instr1_1;
 	  if (busy)	  
	    next_st = ST_WREG2_2;
       end

       ST_WREG2_2: begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b0;     
	  spi_cmd_0 = instr1_1;
          if (~busy)                //Check for busy status 
	    next_st = ST_WREG2_3;
       end

       ST_WREG2_3 : begin
	  spi_cmd_instr_0 = 8'h20;
	  spi_cmd_en_0 = 1'b1;     
	  spi_cmd_0 = instr2_1;
	  spi_wr_data_0 = flash_rd_status_reg1 | 8'h02; // set bit-9 = 1
	  if (busy == 1'b0 && wait_cnt >= 3'd3) begin
	    spi_cmd_en_0 = 1'b0;
	    next_wait_cnt = 3'd0;
	    next_st = ST_WREG2_4;
          end
	  else begin
	    next_wait_cnt = wait_cnt + 1'b1;
          end
       end

       ST_WREG2_4 : begin
	  next_st = ST_CMD2_0;
       end
      
     endcase // case (current_st)
    
  end // always @ (*)
   

   
   always @(posedge clk_in)
     if (rst_in)
       begin
	  spi_wr_data_1 <= 8'h0;
	  spi_cmd_instr_1 <= 8'd0;
	  spi_cmd_en_1 <= 1'b0;
	  spi_cmd_1 <= 5'b0;
	  instr1_1 <= 5'd0;
	  instr2_1 <= 5'd0;
	  busy_1 <= 1'b0;
	  check_busy_1 <= 1'b0;
       end
     else
       begin
	  spi_wr_data_1 <= spi_wr_data_0;
	  spi_cmd_instr_1 <= spi_cmd_instr_0;
	  spi_cmd_en_1 <= spi_cmd_en_0;
	  spi_cmd_1 <= spi_cmd_0;
	  instr1_1 <= instr1_0;
	  instr2_1 <= instr2_0;
	  busy_1 <= (current_st != ST_IDLE);
	  check_busy_1 <= check_busy_0;
       end // else: !if(rst_in)


   always @(posedge clk_in)
     if (rst_in | ((page_write | quad_page_write) & wren))
       begin
	  byte_cnt <= 9'h000;
       end

     else if (wren & shift_bytes)
       begin
	  byte_cnt <= byte_cnt + 1;
       end

   //Support 1-256
   always @(posedge clk_in)
     if (rst_in)
       byte_cnt_out <= 9'h000;
     else if ((page_write | quad_page_write) & wren)
       byte_cnt_out <= byte_cnt;
 
       
   
   always @(posedge clk_in)
     if (rst_in)
       soft_reset <= 6'b00_0001;
     else
       soft_reset <= soft_reset << 1;
   
/////////////////////////
//Sector Erase Steps
/////////////////////////
//Write Enable Instruction
//Erase
//Erase Done? [Check the status register?]

//Test Case
////Set the Erase Command Instruction to Sector Erase (0x20)
//jtag_intreg_write(`INTREG_IP_INSTR,8'h20); //Erase Instruction Command Setting/Type
//jtag_intreg_read(`INTREG_IP_INSTR,8'h20); //Erase Instruction Command Setting/Type
