//jtag_intreg_write(`INTREG_IP_CMD,8'h8e); //Burst fast Read Instruction Command.
//jtag_intreg_write(`INTREG_IP_CMD,8'h00); //Burst Read Instruction Command.   
   
   

endmodule // efx_command_ctl



